$ErrorActionPreference = "Stop"
$Repo = "$env:USERPROFILE\Downloads\CaptivPortal-KB-Work"
$Expected = "53f617b3ac0155d0d647e58e98309927f9a4d318"
$OutPatch = Join-Path $PSScriptRoot "CaptivPortal_KB_Reconciliation_FROM_LOCAL.patch"

function Decode-Utf8([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}
function Replace-ExactLf([string]$RelPath, [string]$Old64, [string]$New64) {
    $Path = Join-Path $Repo $RelPath
    if (-not (Test-Path $Path)) { throw "STOP: missing $RelPath" }
    $Text = [IO.File]::ReadAllText($Path).Replace("`r`n","`n")
    $Old = (Decode-Utf8 $Old64).Replace("`r`n","`n")
    $New = (Decode-Utf8 $New64).Replace("`r`n","`n")
    $Count = ([regex]::Matches($Text, [regex]::Escape($Old))).Count
    if ($Count -ne 1) { throw "STOP: expected exactly one target in $RelPath; found $Count" }
    $Text = $Text.Replace($Old,$New)
    [IO.File]::WriteAllText($Path,$Text,(New-Object Text.UTF8Encoding($false)))
}
function Write-NewUtf8Lf([string]$RelPath, [string]$Content64) {
    $Path = Join-Path $Repo $RelPath
    if (Test-Path $Path) { throw "STOP: new file already exists: $RelPath" }
    $Parent = Split-Path -Parent $Path
    New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    $Text = (Decode-Utf8 $Content64).Replace("`r`n","`n")
    [IO.File]::WriteAllText($Path,$Text,(New-Object Text.UTF8Encoding($false)))
}

Write-Host "=== PRECHECK ==="
git -C $Repo fetch origin main
if ($LASTEXITCODE -ne 0) { throw "STOP: fetch failed" }
$Remote = (git -C $Repo rev-parse origin/main).Trim()
Write-Host "origin/main: $Remote"
if ($Remote -ne $Expected) { throw "STOP: main moved; reconciliation must be rebound" }
if (@(git -C $Repo status --porcelain).Count -ne 0) { throw "STOP: working tree is not clean" }
git -C $Repo switch main
if ($LASTEXITCODE -ne 0) { throw "STOP: cannot switch to main" }
git -C $Repo merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "STOP: fast-forward failed" }
if ((git -C $Repo rev-parse HEAD).Trim() -ne $Expected) { throw "STOP: local HEAD mismatch" }

Write-Host "=== APPLY DOCS RECONCILIATION ==="
