Write-Host "=== SCOPE / DIFF CHECK ==="
$ExpectedPaths = @("README.md","README_RU.md","docs/README.md","docs/architecture.md","docs/configuration.md","docs/deployment.md","docs/logging.md","docs/module-index.md","docs/modules/admin-web.md","docs/modules/analytics.md","docs/modules/capport.md","docs/modules/current-state.md","docs/modules/home-activity.md","docs/modules/portal-entry.md","docs/modules/visit-lifecycle.md","docs/postmortems/TASK-HOME-ACTIVITY-01-2026-08-26.md","docs/project-inventory.md","docs/testing.md")
$Actual = @(git -C $Repo status --porcelain | ForEach-Object { $_.Substring(3).Trim() } | Sort-Object -Unique)
$ExpectedSorted = @($ExpectedPaths | Sort-Object -Unique)
if (($Actual -join "`n") -ne ($ExpectedSorted -join "`n")) {
    Write-Host "Expected:"; $ExpectedSorted | ForEach-Object { Write-Host "  $_" }
    Write-Host "Actual:"; $Actual | ForEach-Object { Write-Host "  $_" }
    throw "STOP: changed-file scope mismatch"
}

git -C $Repo diff --check
if ($LASTEXITCODE -ne 0) { throw "STOP: git diff --check failed" }

# Current-state contradiction guard.
$Forbidden = @(
    "Home Activity is not current code at this baseline",
    "Home Activity implementation.",
    "Strict suite: 1985 passed / 30 skipped / 0 strict regressions",
    "strict suite: 1985 passed / 30 skipped / 0 strict regressions",
    "NEXT: Home Activity",
    "СЛЕДУЮЩИЙ: Home Activity"
)
foreach ($Needle in $Forbidden) {
    $Hit = git -C $Repo grep -n -F -- "$Needle" -- README.md README_RU.md docs
    if ($LASTEXITCODE -eq 0 -and $Hit) {
        Write-Host $Hit
        throw "STOP: stale current-state phrase remains: $Needle"
    }
}

git -C $Repo diff --no-ext-diff --binary -- @($ExpectedPaths) | Out-File -FilePath $OutPatch -Encoding utf8
Write-Host "PASS: docs-only reconciliation applied locally"
Write-Host "Generated unified diff: $OutPatch"
Write-Host "NO COMMIT / NO PUSH / NO PR / NO MERGE"
